import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync,writeFileSync,existsSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {planWithRegistry,runRegistryCommand} from '../packages/architect/src/registry.ts';
import type {RegistryResponse} from '../packages/architect/src/registry.ts';
function sandbox(fn:(db:string)=>void){const d=mkdtempSync(join(tmpdir(),'Ywoom-reg-'));try{fn(join(d,'registry.sqlite'));}finally{rmSync(d,{recursive:true,force:true});}}
function cap(version='v1'){return {id:'local2d',version,fidelities:['2d_approximation'],controls:['reference_image'],requiredAssetKinds:['image'],maxDurationSec:60,price:{currency:'USD',fixedMinor:10,perSecondMinor:1,minimumSeconds:1,roundingSeconds:1}};}
function ev(sourceType:'fixture'|'official_document'|'benchmark'='official_document',expiresAt='2099-01-01T00:00:00Z'){return [{id:'e1',sourceType,sourceUri:'https://example.invalid/evidence',sha256:'a'.repeat(64),observedAt:'2026-10-03T00:00:00Z',expiresAt}];}
function register(db:string,sourceType:'fixture'|'official_document'|'benchmark'='official_document',expiresAt?:string,version='v1'){return runRegistryCommand(db,{kind:'register',commandId:'reg-'+version,id:'local2d',version,actor:{id:'registrar',role:'capability_registrar'},capability:cap(version),evidence:ev(sourceType,expiresAt),reason:'offline test declaration'});}
function code(r:RegistryResponse){assert.equal(r.ok,false);if(r.ok)throw Error('expected reject');return r.code;}
function recordVersion(r:RegistryResponse){assert(r.ok&&'record'in r);return r.record.recordVersion;}
function verify(db:string,version='v1'){return runRegistryCommand(db,{kind:'verify',commandId:'verify-'+version,id:'local2d',version,expectedRecordVersion:1,actor:{id:'verifier',role:'capability_verifier'}});}
function approve(db:string,version='v1'){return runRegistryCommand(db,{kind:'approve',commandId:'approve-'+version,id:'local2d',version,expectedRecordVersion:2,actor:{id:'approver',role:'capability_approver'}});}
function plan(version='v1',asOf='2026-10-04T00:00:00Z'){return {schemaVersion:1,unitId:'u1',revision:1,scenes:[{id:'s1',durationSec:10,fidelity:'2d_approximation',controls:['reference_image'],assetIds:['a1'],protectedAssetIds:['a1']}],assets:[{id:'a1',kind:'image',sha256:'b'.repeat(64)}],capabilityPins:[{id:'local2d',version}],budget:{baselineMinor:100,repairPercent:20,projectRemainingMinor:1000,monthRemainingMinor:1000},localCost:{assemblyMinor:5,qaMinor:5},asOf};}
function issue(db:string,p=plan()){const r=planWithRegistry(db,p);assert(r.ok);return r.report.issues.map(x=>x.code);}
test('candidate declaration is stored but planner rejects it',()=>sandbox(db=>{const r=register(db);assert.equal(recordVersion(r),1);assert.deepEqual(issue(db),['registry_capability_unapproved','unsupported_scene']);}));
test('verified capability still requires independent approval',()=>sandbox(db=>{register(db);verify(db);assert(issue(db).includes('registry_capability_unapproved'));}));
test('approved pinned capability is resolved and produces a non-executable plan',()=>sandbox(db=>{register(db);verify(db);approve(db);const r=planWithRegistry(db,plan());assert(r.ok);assert.equal(r.report.status,'ready_for_review');assert.equal(r.report.executionAllowed,false);assert.deepEqual(r.report.registryPins[0]?.evidenceIds,['e1']);assert.equal(r.report.nodes[0]?.capabilityVersion,'v1');}));
test('revocation blocks an already known pinned version',()=>sandbox(db=>{register(db);verify(db);approve(db);const x=runRegistryCommand(db,{kind:'revoke',commandId:'revoke-v1',id:'local2d',version:'v1',expectedRecordVersion:3,actor:{id:'security',role:'security_reviewer'},reason:'evidence withdrawn'});assert.equal(recordVersion(x),4);assert(issue(db).includes('registry_capability_revoked'));}));
test('approved evidence expiry is evaluated at planning time',()=>sandbox(db=>{register(db,'official_document','2099-01-01T00:00:00Z');verify(db);approve(db);assert(issue(db,plan('v1','2100-01-01T00:00:00Z')).includes('registry_evidence_expired'));}));
test('fixture declaration cannot be called verified evidence',()=>sandbox(db=>{register(db,'fixture');assert.equal(code(verify(db)),'verification_basis_required');}));
test('verifier cannot approve own verification',()=>sandbox(db=>{register(db);verify(db);assert.equal(code(runRegistryCommand(db,{kind:'approve',commandId:'bad-approve',id:'local2d',version:'v1',expectedRecordVersion:2,actor:{id:'verifier',role:'capability_approver'}})),'independent_approval_required');}));
test('wrong actor role cannot verify',()=>sandbox(db=>{register(db);assert.equal(code(runRegistryCommand(db,{kind:'verify',commandId:'bad-role',id:'local2d',version:'v1',expectedRecordVersion:1,actor:{id:'registrar',role:'capability_registrar'}})),'unauthorized_actor_role');}));
test('exact version pin never floats to another approved version',()=>sandbox(db=>{register(db);verify(db);approve(db);register(db,'official_document',undefined,'v2');verify(db,'v2');approve(db,'v2');const r=planWithRegistry(db,plan('v1'));assert(r.ok);assert.equal(r.report.nodes[0]?.capabilityVersion,'v1');}));
test('missing pin fails closed instead of trusting request flags',()=>sandbox(db=>{register(db);assert(issue(db,plan('v9')).includes('registry_pin_missing'));}));
test('caller cannot inject capabilities into registered planner contract',()=>sandbox(db=>{register(db);const p={...plan(),capabilities:[cap()]};const r=planWithRegistry(db,p);assert.equal(r.ok,false);}));
test('registry commands are idempotent and conflicting reuse is denied',()=>sandbox(db=>{const a=register(db);const b=register(db);assert(a.ok&&b.ok&&'replayed'in b&&b.replayed);const changed={kind:'register',commandId:'reg-v1',id:'local2d',version:'v1',actor:{id:'registrar',role:'capability_registrar'},capability:cap(),evidence:ev('benchmark'),reason:'changed'};assert.equal(code(runRegistryCommand(db,changed)),'idempotency_conflict');}));
test('duplicate capability pins are rejected',()=>sandbox(db=>{const p=plan();p.capabilityPins.push({...p.capabilityPins[0]!});assert.equal(planWithRegistry(db,p).ok,false);}));
import {runRegisteredStoreCommand} from '../packages/architect/src/store.ts';
test('registered store path persists registry-resolved plan and snapshot',()=>sandbox(registry=>{register(registry);verify(registry);approve(registry);const d=mkdtempSync(join(tmpdir(),'Ywoom-reg-state-'));try{const state=join(d,'state.sqlite');const r=runRegisteredStoreCommand(state,registry,{kind:'createRegistered',commandId:'create-reg',expectedVersion:0,plan:plan()});assert(r.ok&&'state'in r);assert.equal((r.state.planReport as {registryPins:unknown[]}).registryPins.length,1);assert.equal(r.state.executionAllowed,false);}finally{rmSync(d,{recursive:true,force:true});}}));
test('registered store path rejects candidate before persistence',()=>sandbox(registry=>{register(registry);const d=mkdtempSync(join(tmpdir(),'Ywoom-reg-state-'));try{const r=runRegisteredStoreCommand(join(d,'state.sqlite'),registry,{kind:'createRegistered',commandId:'create-reg',expectedVersion:0,plan:plan()});assert.equal(r.ok,true);if(r.ok&&'state'in r){assert.equal(r.state.state,'blocked');assert.equal(r.state.executionAllowed,false);}}finally{rmSync(d,{recursive:true,force:true});}}));
import {spawn,spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {generateKeyPairSync,sign} from 'node:crypto';
import {authoritySigningPayload,runAuthorizedRegistryCommand} from '../packages/architect/src/authority.ts';
test('registry rejects malformed capability fields before persistence',()=>sandbox(db=>{const c={...cap(),maxDurationSec:0};const r=runRegistryCommand(db,{kind:'register',commandId:'bad-cap',id:'local2d',version:'v1',actor:{id:'registrar',role:'capability_registrar'},capability:c,evidence:ev(),reason:'bad'});assert.equal(code(r),'invalid_integer');}));
test('registry append-only event trigger denies rewriting history',()=>sandbox(db=>{register(db);const r=spawnSync('python3',['-c',"import sqlite3,sys;c=sqlite3.connect(sys.argv[1]);c.execute('DELETE FROM events')",db],{encoding:'utf8'});assert.notEqual(r.status,0);assert.match(r.stderr,/append_only/);}));
test('registry projection tampering is detected',()=>sandbox(db=>{register(db);spawnSync('python3',['-c',"import sqlite3,sys;c=sqlite3.connect(sys.argv[1]);c.execute('UPDATE capabilities SET version=99');c.commit()",db]);assert.equal(code(runRegistryCommand(db,{kind:'get',id:'local2d',version:'v1'})),'integrity_failure');}));
test('registry event chain tampering is detected even if DB owner drops trigger',()=>sandbox(db=>{register(db);spawnSync('python3',['-c',"import sqlite3,sys;c=sqlite3.connect(sys.argv[1]);c.execute('DROP TRIGGER capability_events_no_update');c.execute(\"UPDATE events SET previous_hash='x'\");c.commit()",db]);assert.equal(code(runRegistryCommand(db,{kind:'get',id:'local2d',version:'v1'})),'integrity_failure');}));
test('foreign and old-schema SQLite databases are rejected',()=>sandbox(db=>{spawnSync('python3',['-c',"import sqlite3,sys;c=sqlite3.connect(sys.argv[1]);c.execute('PRAGMA application_id=1364618563');c.execute('PRAGMA user_version=1');c.commit()",db]);assert.equal(code(register(db)),'unsupported_database');}));
test('two first writers cannot both initialize the same registry',async()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-reg-race-'));const db=join(d,'registry.sqlite'),worker=fileURLToPath(new URL('../workers/architect/registry.py',import.meta.url));try{const request=(id:string)=>JSON.stringify({kind:'register',commandId:'reg-'+id,id:'cap'+id,version:'v1',actor:{id:'registrar',role:'capability_registrar'},capability:{...cap(),id:'cap'+id},evidence:ev(),reason:'race'});const launch=(id:string)=>new Promise<RegistryResponse>((resolve,reject)=>{const p=spawn('python3',[worker,db]);let out='';p.stdout.on('data',(b:Buffer)=>out+=b.toString());p.on('error',reject);p.on('close',()=>{try{resolve(JSON.parse(out) as RegistryResponse);}catch(e){reject(e);}});p.stdin.end(request(id));});const rs=await Promise.all([launch('a'),launch('b')]);assert.equal(rs.every(x=>x.ok||x.code==='initialization_busy'),true);assert.equal(rs.some(x=>x.ok),true);if(rs.every(x=>x.ok)){const listed=runRegistryCommand(db,{kind:'list'});assert(listed.ok&&'records'in listed);assert.equal(listed.records.length,2);}}finally{rmSync(d,{recursive:true,force:true});}});
function key(id:string,roles:string[]){const pair=generateKeyPairSync('ed25519');return {id,roles,privateKey:pair.privateKey,publicKeyPem:pair.publicKey.export({type:'spki',format:'pem'}).toString()};}
function envelope(registryId:string,policyVersion:number,principal:{id:string;privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']},command:Record<string,unknown>){const unsigned={schemaVersion:1 as const,registryId,policyVersion,principalId:principal.id,command};return {...unsigned,signature:sign(null,authoritySigningPayload(unsigned),principal.privateKey).toString('base64')};}
test('signed authority adapter admits separated registrar verifier and approver',()=>sandbox(db=>{const a=key('registrar',['capability_registrar']),v=key('verifier',['capability_verifier']),p=key('approver',['capability_approver']);const policy={schemaVersion:1,registryId:'reg1',policyVersion:7,principals:[a,v,p].map(x=>({id:x.id,roles:x.roles,publicKeyPem:x.publicKeyPem}))};const reg={kind:'register',commandId:'signed-reg',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'signed'};assert(runAuthorizedRegistryCommand(db,policy,envelope('reg1',7,a,reg)).ok);assert(runAuthorizedRegistryCommand(db,policy,envelope('reg1',7,v,{kind:'verify',commandId:'signed-verify',id:'local2d',version:'v1',expectedRecordVersion:1})).ok);const r=runAuthorizedRegistryCommand(db,policy,envelope('reg1',7,p,{kind:'approve',commandId:'signed-approve',id:'local2d',version:'v1',expectedRecordVersion:2}));assert(r.ok&&'record'in r);assert.equal(r.record.status,'approved');}));
test('authority adapter rejects wrong role, registry and policy versions',()=>sandbox(db=>{const a=key('registrar',['capability_registrar']);const policy={schemaVersion:1,registryId:'reg1',policyVersion:7,principals:[{id:a.id,roles:a.roles,publicKeyPem:a.publicKeyPem}]};const command={kind:'verify',commandId:'v',id:'local2d',version:'v1',expectedRecordVersion:1};assert.equal(code(runAuthorizedRegistryCommand(db,policy,envelope('reg1',7,a,command))),'authority_role_denied');assert.equal(code(runAuthorizedRegistryCommand(db,policy,envelope('reg2',7,a,command))),'invalid_authority_envelope');assert.equal(code(runAuthorizedRegistryCommand(db,policy,envelope('reg1',6,a,command))),'invalid_authority_envelope');}));
test('authority signature covers the complete command and denies actor injection',()=>sandbox(db=>{const a=key('registrar',['capability_registrar']);const policy={schemaVersion:1,registryId:'reg1',policyVersion:1,principals:[{id:a.id,roles:a.roles,publicKeyPem:a.publicKeyPem}]};const command={kind:'register',commandId:'r',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'signed'};const e=envelope('reg1',1,a,command);(e.command as Record<string,unknown>)['reason']='tampered';assert.equal(code(runAuthorizedRegistryCommand(db,policy,e)),'invalid_signature');const injected=envelope('reg1',1,a,{...command,actor:{id:'x',role:'capability_approver'}});assert.equal(code(runAuthorizedRegistryCommand(db,policy,injected)),'actor_injection_denied');}));
test('stale or live initialization lock fails closed without deleting it',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-reg-lock-'));try{const db=join(d,'registry.sqlite');const lock=db+'.init-lock';writeFileSync(lock,'held');assert.equal(code(register(db)),'initialization_busy');assert.equal(existsSync(lock),true);assert.equal(existsSync(db),false);}finally{rmSync(d,{recursive:true,force:true});}});
import {authorityPolicyPayload,authorityRootFingerprint,runAuthorityPolicyCommand,runPinnedAuthorizedRegistryCommand} from '../packages/architect/src/authority-store.ts';
import type {StoredAuthorityPolicy} from '../packages/architect/src/authority-store.ts';
function storedPolicy(root:{publicKeyPem:string},principals:Array<{id:string;roles:string[];publicKeyPem:string}>,version=1,validFrom='2026-01-01T00:00:00Z',expiresAt='2099-01-01T00:00:00Z'):StoredAuthorityPolicy{return {schemaVersion:1,registryId:'reg1',policyVersion:version,validFrom,expiresAt,rootPublicKeyPem:root.publicKeyPem,principals:principals.map(x=>({id:x.id,roles:x.roles as StoredAuthorityPolicy['principals'][number]['roles'],publicKeyPem:x.publicKeyPem}))};}
function policyCommand(kind:'bootstrap'|'rotate',commandId:string,expectedVersion:number,policy:StoredAuthorityPolicy,root:{privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']}){return {kind,commandId,expectedVersion,policy,rootSignature:sign(null,authorityPolicyPayload(policy),root.privateKey).toString('base64')};}
test('root-signed authority policy bootstraps and restores from a fresh process',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),policy=storedPolicy(root,[a]),anchor=authorityRootFingerprint(root.publicKeyPem);const created=runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','policy-1',0,policy,root));assert(created.ok&&created.version===1);const loaded=runAuthorityPolicyCommand(db,anchor,{kind:'get'});assert(loaded.ok&&loaded.policy.registryId==='reg1');}finally{rmSync(d,{recursive:true,force:true});}});
test('authority policy bootstrap rejects wrong anchor and root signature',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),other=key('other',['security_reviewer']),a=key('registrar',['capability_registrar']),policy=storedPolicy(root,[a]),anchor=authorityRootFingerprint(root.publicKeyPem);assert.equal((runAuthorityPolicyCommand(db,'0'.repeat(64),policyCommand('bootstrap','policy-1',0,policy,root)) as {code?:string}).code,'authority_anchor_mismatch');assert.equal((runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','policy-1',0,policy,other)) as {code?:string}).code,'invalid_root_signature');}finally{rmSync(d,{recursive:true,force:true});}});
test('current root can rotate policy and root while anchor remains pinned',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),next=key('next',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p1=storedPolicy(root,[a]);assert(runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p1,root)).ok);const p2=storedPolicy(next,[a],2);const r=runAuthorityPolicyCommand(db,anchor,policyCommand('rotate','p2',1,p2,root));assert(r.ok&&r.policy.rootPublicKeyPem===next.publicKeyPem);const p3=storedPolicy(next,[a],3);assert(runAuthorityPolicyCommand(db,anchor,policyCommand('rotate','p3',2,p3,next)).ok);}finally{rmSync(d,{recursive:true,force:true});}});
test('policy rotation rejects stale version and non-current signer',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),other=key('other',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p1=storedPolicy(root,[a]);runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p1,root));const p2=storedPolicy(root,[a],2);assert.equal((runAuthorityPolicyCommand(db,anchor,policyCommand('rotate','bad',0,p2,root)) as {code?:string}).code,'policy_version_conflict');assert.equal((runAuthorityPolicyCommand(db,anchor,policyCommand('rotate','bad2',1,p2,other)) as {code?:string}).code,'invalid_root_signature');}finally{rmSync(d,{recursive:true,force:true});}});
test('authority policy projection tampering is detected',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[a]);runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p,root));spawnSync('python3',['-c',"import sqlite3,sys;c=sqlite3.connect(sys.argv[1]);c.execute('UPDATE current_policy SET version=9');c.commit()",db]);assert.equal((runAuthorityPolicyCommand(db,anchor,{kind:'get'}) as {code?:string}).code,'integrity_failure');}finally{rmSync(d,{recursive:true,force:true});}});
test('pinned adapter loads stored policy and admits no caller replacement policy',()=>sandbox(registry=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const auth=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[a]);runAuthorityPolicyCommand(auth,anchor,policyCommand('bootstrap','p1',0,p,root));const command={kind:'register',commandId:'pinned-reg',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'pinned'};const r=runPinnedAuthorizedRegistryCommand(registry,auth,anchor,envelope('reg1',1,a,command),()=>new Date('2026-10-03T00:00:00Z'));assert(r.ok);assert.equal(code(runPinnedAuthorizedRegistryCommand(registry,auth,'0'.repeat(64),envelope('reg1',1,a,command),()=>new Date('2026-10-03T00:00:00Z'))),'authority_anchor_mismatch');}finally{rmSync(d,{recursive:true,force:true});}}));
test('pinned adapter rejects expired and not-yet-valid policies',()=>sandbox(registry=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const auth=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[a],1,'2030-01-01T00:00:00Z','2040-01-01T00:00:00Z');runAuthorityPolicyCommand(auth,anchor,policyCommand('bootstrap','p1',0,p,root));const e=envelope('reg1',1,a,{kind:'register',commandId:'r',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'time'});assert.equal(code(runPinnedAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2029-01-01T00:00:00Z'))),'authority_policy_not_yet_valid');assert.equal(code(runPinnedAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2040-01-01T00:00:00Z'))),'authority_policy_expired');}finally{rmSync(d,{recursive:true,force:true});}}));
test('rotated policy revokes removed principal immediately by version',()=>sandbox(registry=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const auth=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),b=key('backup',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p1=storedPolicy(root,[a,b]);runAuthorityPolicyCommand(auth,anchor,policyCommand('bootstrap','p1',0,p1,root));const p2=storedPolicy(root,[b],2);runAuthorityPolicyCommand(auth,anchor,policyCommand('rotate','p2',1,p2,root));const command={kind:'register',commandId:'revoked',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'revoked'};assert.equal(code(runPinnedAuthorizedRegistryCommand(registry,auth,anchor,envelope('reg1',1,a,command),()=>new Date('2026-10-03T00:00:00Z'))),'invalid_authority_envelope');assert.equal(code(runPinnedAuthorizedRegistryCommand(registry,auth,anchor,envelope('reg1',2,a,command),()=>new Date('2026-10-03T00:00:00Z'))),'unknown_principal');}finally{rmSync(d,{recursive:true,force:true});}}));
test('authority policy rejects malformed root and principal keys before persistence',()=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),a=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[a]);p.principals[0]!.publicKeyPem='not-a-key';assert.equal((runAuthorityPolicyCommand(db,anchor,{kind:'bootstrap',commandId:'bad',expectedVersion:0,policy:p,rootSignature:'x'}) as {code?:string}).code,'invalid_command');}finally{rmSync(d,{recursive:true,force:true});}});
import {runConsumableAuthorizedRegistryCommand,timedAuthoritySigningPayload,verifyTimedAuthorityEnvelope} from '../packages/architect/src/authority-store.ts';
import type {TimedSignedRegistryEnvelope} from '../packages/architect/src/authority-store.ts';
function timedEnvelope(principal:{id:string;privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']},command:Record<string,unknown>,authorizationId='auth1',issuedAt='2026-10-03T00:00:00Z',expiresAt='2026-10-03T00:10:00Z',policyVersion=1):TimedSignedRegistryEnvelope{const unsigned={schemaVersion:1 as const,registryId:'reg1',policyVersion,principalId:principal.id,purpose:'capability_registry_mutation' as const,authorizationId,issuedAt,expiresAt,command};return {...unsigned,signature:sign(null,timedAuthoritySigningPayload(unsigned),principal.privateKey).toString('base64')};}
function authoritySandbox(fn:(db:string,anchor:string,registrar:ReturnType<typeof key>)=>void){const d=mkdtempSync(join(tmpdir(),'Ywoom-authz-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),registrar=key('registrar',['capability_registrar']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[registrar]);assert(runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p,root)).ok);fn(db,anchor,registrar);}finally{rmSync(d,{recursive:true,force:true});}}
test('time-bound envelope verifies purpose audience and fifteen-minute maximum',()=>authoritySandbox((db,anchor,a)=>{const cmd={kind:'register',commandId:'r1',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'timed'};assert(verifyTimedAuthorityEnvelope(db,anchor,timedEnvelope(a,cmd),()=>new Date('2026-10-03T00:05:00Z')).ok);const long=timedEnvelope(a,cmd,'long','2026-10-03T00:00:00Z','2026-10-03T00:15:01Z');assert.equal((verifyTimedAuthorityEnvelope(db,anchor,long,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'authorization_time_invalid');}));
test('unconsumed timed envelope fails before issue and at expiry',()=>authoritySandbox((db,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'r1',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'timed'});assert.equal((verifyTimedAuthorityEnvelope(db,anchor,e,()=>new Date('2026-10-02T23:59:59Z')) as {code?:string}).code,'authorization_time_invalid');assert.equal((verifyTimedAuthorityEnvelope(db,anchor,e,()=>new Date('2026-10-03T00:10:00Z')) as {code?:string}).code,'authorization_time_invalid');}));
test('timed signature covers purpose authorization id and command',()=>authoritySandbox((db,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'r1',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'timed'});const tampered={...e,authorizationId:'other'};assert.equal((verifyTimedAuthorityEnvelope(db,anchor,tampered,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_signature');const wrong={...e,registryId:'reg2'};assert.equal((verifyTimedAuthorityEnvelope(db,anchor,wrong,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_timed_authority_envelope');}));
test('consumable authorization mutates registry once and exact replay returns receipt',()=>sandbox(registry=>authoritySandbox((auth,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'timed-reg',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'timed'});const first=runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:05:00Z'));assert(first.ok&&'replayed'in first&&!first.replayed);const replay=runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:06:00Z'));assert(replay.ok&&'replayed'in replay&&replay.replayed);}))); 
test('consumed exact envelope can recover receipt after command expiry',()=>sandbox(registry=>authoritySandbox((auth,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'timed-reg',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'timed'});assert(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:05:00Z')).ok);const replay=runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:11:00Z'));assert(replay.ok&&'replayed'in replay&&replay.replayed);}))); 
test('unconsumed expired authorization cannot mutate registry',()=>sandbox(registry=>authoritySandbox((auth,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'late',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'late'});assert.equal(code(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:11:00Z'))),'authorization_time_invalid');assert.equal(code(runRegistryCommand(registry,{kind:'get',id:'local2d',version:'v1'})),'not_found');})));
test('authorization id cannot be reused for a different signed command',()=>sandbox(registry=>authoritySandbox((auth,anchor,a)=>{const one=timedEnvelope(a,{kind:'register',commandId:'one',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'one'},'same');assert(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,one,()=>new Date('2026-10-03T00:05:00Z')).ok);const two=timedEnvelope(a,{kind:'register',commandId:'two',id:'other',version:'v1',capability:{...cap(),id:'other'},evidence:ev(),reason:'two'},'same');assert.equal(code(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,two,()=>new Date('2026-10-03T00:06:00Z'))),'authorization_reuse_conflict');})));
