import {getAuthorityOperation,listPendingAuthorityOperations,operationStopSigningPayload,stopAuthorityOperation} from '../packages/architect/src/authority-store.ts';
import type {SignedOperationStop} from '../packages/architect/src/authority-store.ts';
function stopEnvelope(principal:{id:string;privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']},authorizationId:string,reason='operator stop'):SignedOperationStop{const unsigned={schemaVersion:1 as const,registryId:'reg1',policyVersion:1,principalId:principal.id,purpose:'authority_operation_stop' as const,authorizationId,reason,issuedAt:'2026-10-03T00:00:00Z',expiresAt:'2026-10-03T00:10:00Z'};return {...unsigned,signature:sign(null,operationStopSigningPayload(unsigned),principal.privateKey).toString('base64')};}
function authorityWithSecurity(fn:(db:string,anchor:string,registrar:ReturnType<typeof key>,security:ReturnType<typeof key>)=>void){const d=mkdtempSync(join(tmpdir(),'Ywoom-ops-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),registrar=key('registrar',['capability_registrar']),security=key('security',['security_reviewer']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[registrar,security]);assert(runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p,root)).ok);fn(db,anchor,registrar,security);}finally{rmSync(d,{recursive:true,force:true});}}
const authorityWorker=fileURLToPath(new URL('../workers/architect/authority_store.py',import.meta.url));
function claimOnly(auth:string,anchor:string,envelope:TimedSignedRegistryEnvelope,at='2026-10-03T00:05:00Z'){const verified=verifyTimedAuthorityEnvelope(auth,anchor,envelope,()=>new Date(at));assert(verified.ok);const request={action:'consume',authorizationId:envelope.authorizationId,envelopeHash:verified.envelopeHash,commandId:verified.command['commandId'],policyVersion:envelope.policyVersion,issuedAtMs:verified.issuedAtMs,expiresAtMs:verified.expiresAtMs,nowMs:new Date(at).getTime(),envelope};const r=spawnSync('python3',[authorityWorker,auth],{input:JSON.stringify(request),encoding:'utf8'});assert.equal(r.status,0);const out=JSON.parse(r.stdout) as {ok:boolean};assert(out.ok);}
test('coordinator records completed registry receipt and leaves no pending item',()=>sandbox(registry=>authorityWithSecurity((auth,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'coord-done',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'done'},'coord-done');assert(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:05:00Z')).ok);const got=getAuthorityOperation(auth,'coord-done');assert(got.ok&&'operation'in got);assert.equal(got.operation.state,'completed');assert(got.operation.result?.ok);const pending=listPendingAuthorityOperations(auth);assert(pending.ok&&'operations'in pending);assert.equal(pending.operations.length,0);}))); 
test('claimed operation survives restart and exact replay completes it',()=>authorityWithSecurity((auth,anchor,a)=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-coord-'));try{const registry=join(d,'registry.sqlite');const e=timedEnvelope(a,{kind:'register',commandId:'coord-pending',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'pending'},'coord-pending');claimOnly(auth,anchor,e);const pending=listPendingAuthorityOperations(auth);assert(pending.ok&&'operations'in pending);assert.equal(pending.operations[0]?.authorizationId,'coord-pending');const replay=runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:06:00Z'));assert(replay.ok);const got=getAuthorityOperation(auth,'coord-pending');assert(got.ok&&'operation'in got);assert.equal(got.operation.state,'completed');}finally{rmSync(d,{recursive:true,force:true});}}));
test('pending listing persists complete signed envelope for exact replay only',()=>authorityWithSecurity((auth,anchor,a)=>{const e=timedEnvelope(a,{kind:'register',commandId:'coord-envelope',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'pending'},'coord-envelope');claimOnly(auth,anchor,e);const pending=listPendingAuthorityOperations(auth);assert(pending.ok&&'operations'in pending);assert.deepEqual(pending.operations[0]?.envelope,e);}));
test('security reviewer can stop claimed operation and future replay is denied',()=>authorityWithSecurity((auth,anchor,a,security)=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-stop-'));try{const registry=join(d,'registry.sqlite');const e=timedEnvelope(a,{kind:'register',commandId:'stop-me',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'pending'},'stop-me');claimOnly(auth,anchor,e);const stopped=stopAuthorityOperation(auth,anchor,stopEnvelope(security,'stop-me'),()=>new Date('2026-10-03T00:05:00Z'));assert(stopped.ok&&'operation'in stopped);assert.equal(stopped.operation.state,'stopped');assert.equal(code(runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:06:00Z'))),'operation_stopped');const pending=listPendingAuthorityOperations(auth);assert(pending.ok&&'operations'in pending);assert.equal(pending.operations.length,0);}finally{rmSync(d,{recursive:true,force:true});}}));
test('registrar cannot stop and stop signature covers reason',()=>authorityWithSecurity((auth,anchor,a,security)=>{const denied=stopAuthorityOperation(auth,anchor,stopEnvelope(a,'missing'),()=>new Date('2026-10-03T00:05:00Z'));assert.equal((denied as {code?:string}).code,'authority_role_denied');const e=stopEnvelope(security,'missing');e.reason='tampered';assert.equal((stopAuthorityOperation(auth,anchor,e,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_signature');}));
test('completed operation cannot be stopped',()=>sandbox(registry=>authorityWithSecurity((auth,anchor,a,security)=>{const e=timedEnvelope(a,{kind:'register',commandId:'already-done',id:'local2d',version:'v1',capability:cap(),evidence:ev(),reason:'done'},'already-done');runConsumableAuthorizedRegistryCommand(registry,auth,anchor,e,()=>new Date('2026-10-03T00:05:00Z'));const r=stopAuthorityOperation(auth,anchor,stopEnvelope(security,'already-done'),()=>new Date('2026-10-03T00:06:00Z'));assert.equal((r as {code?:string}).code,'completed_operation');})));
