import {budgetSnapshotHash,planApprovalSigningPayload,verifySignedPlanApproval} from '../packages/architect/src/plan-approval.ts';
import type {SignedPlanApproval} from '../packages/architect/src/plan-approval.ts';
import {checkPersistedPlanApproval,runPlanApprovalCommand,runStoreCommand} from '../packages/architect/src/store.ts';
function authorityWithPlanApprover(fn:(db:string,anchor:string,approver:ReturnType<typeof key>)=>void){const d=mkdtempSync(join(tmpdir(),'Ywoom-plan-auth-'));try{const db=join(d,'authority.sqlite'),root=key('root',['security_reviewer']),approver=key('planapprover',['plan_approver']),anchor=authorityRootFingerprint(root.publicKeyPem),p=storedPolicy(root,[approver]);assert(runAuthorityPolicyCommand(db,anchor,policyCommand('bootstrap','p1',0,p,root)).ok);fn(db,anchor,approver);}finally{rmSync(d,{recursive:true,force:true});}}
function signedPlanApproval(approver:{id:string;privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']},report:RegistryPlanReport,budget=plan().budget,approvalId='approval1',issuedAt='2026-10-03T00:00:00Z',expiresAt='2026-10-03T00:10:00Z'):SignedPlanApproval{const unsigned={schemaVersion:1 as const,registryId:'reg1',policyVersion:1,principalId:approver.id,purpose:'plan_admission_approval' as const,approvalId,unitId:report.unitId,revision:report.revision,admissionHash:report.admissionHash,budgetSnapshotHash:budgetSnapshotHash(budget),issuedAt,expiresAt};return {...unsigned,signature:sign(null,planApprovalSigningPayload(unsigned),approver.privateKey).toString('base64')};}
function readyRegistry(db:string){register(db);verify(db);approve(db);const p=planWithRegistry(db,plan());assert(p.ok);return p.report;}
test('plan approver signs exact admission and budget without enabling execution',()=>sandbox(registry=>authorityWithPlanApprover((auth,anchor,a)=>{const report=readyRegistry(registry),approval=signedPlanApproval(a,report);const r=verifySignedPlanApproval(auth,anchor,approval,report,plan().budget,()=>new Date('2026-10-03T00:05:00Z'));assert(r.ok);assert.equal(r.report.executionAllowed,false);assert.equal(r.report.budgetReserved,false);}))); 
test('plan approval rejects wrong role, changed budget and expired window',()=>sandbox(registry=>{const report=readyRegistry(registry);authorityWithSecurity((auth,anchor,registrar)=>{const wrong=signedPlanApproval(registrar,report);assert.equal((verifySignedPlanApproval(auth,anchor,wrong,report,plan().budget,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'plan_approver_required');});authorityWithPlanApprover((auth,anchor,a)=>{const approval=signedPlanApproval(a,report);assert.equal((verifySignedPlanApproval(auth,anchor,approval,report,{...plan().budget,baselineMinor:101},()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_plan_approval');assert.equal((verifySignedPlanApproval(auth,anchor,approval,report,plan().budget,()=>new Date('2026-10-03T00:11:00Z')) as {code?:string}).code,'invalid_plan_approval');});}));
test('tampering plan approval binding invalidates signature or contract',()=>sandbox(registry=>authorityWithPlanApprover((auth,anchor,a)=>{const report=readyRegistry(registry),approval=signedPlanApproval(a,report);const changed={...approval,approvalId:'other'};assert.equal((verifySignedPlanApproval(auth,anchor,changed,report,plan().budget,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_signature');const revision={...approval,revision:2};assert.equal((verifySignedPlanApproval(auth,anchor,revision,report,plan().budget,()=>new Date('2026-10-03T00:05:00Z')) as {code?:string}).code,'invalid_plan_approval');})));
