import {runReservationReconciliationCommand,runReservationUnknownCommand} from '../packages/architect/src/store.ts';
function signedReconciliation(attestor:{id:string;privateKey:ReturnType<typeof generateKeyPairSync>['privateKey']},intent:ReservationIntent,receiptId:string,outcome:'pending'|'confirmed'|'unknown'|'released',reconciliationId='reconcile1',method:'lookup'|'poll'='lookup',observedAt='2026-10-03T00:04:00Z',issuedAt='2026-10-03T00:05:00Z',expiresAt='2026-10-03T00:10:00Z'):SignedReservationReconciliationReceipt{const reservedMinor=outcome==='confirmed'?intent.initialMinor:outcome==='released'?0:null;const unsigned={schemaVersion:1 as const,registryId:'reg1',policyVersion:1,principalId:attestor.id,purpose:'local_reservation_reconciliation' as const,reconciliationId,receiptId,intentId:intent.intentId,intentHash:intent.intentHash,unitId:intent.unitId,attemptId:intent.attemptId,method,outcome,reservedMinor,observedAt,issuedAt,expiresAt};return {...unsigned,signature:sign(null,reservationReconciliationSigningPayload(unsigned),attestor.privateKey).toString('base64')};}
function withReservationEvidence(fn:(state:string,registry:string,auth:string,anchor:string,attestor:ReturnType<typeof key>,intent:ReservationIntent,receipt:SignedReservationReceipt)=>void){withPreparedAttempt((state,registry)=>{const prepared=runReservationIntentCommand(state,registry,{kind:'prepareReservation',commandId:'intent-outcome',expectedVersion:3,unitId:'u1',intentId:'intent-outcome'},()=>new Date('2026-10-03T00:03:00Z'));assert(prepared.ok&&'state'in prepared);const intent=prepared.state.reservationIntent as ReservationIntent;authorityWithReservationAttestor((auth,anchor,attestor)=>{const receipt=signedReservation(attestor,intent,'receipt-outcome');const saved=runReservationEvidenceCommand(state,auth,anchor,{kind:'recordReservation',commandId:'evidence-outcome',expectedVersion:4,unitId:'u1',receipt},()=>new Date('2026-10-03T00:05:00Z'));assert(saved.ok);fn(state,registry,auth,anchor,attestor,intent,receipt);});});}
test('reservation intent starts pending with full nonzero liability bound',()=>withPreparedAttempt((state,registry)=>{const r=runReservationIntentCommand(state,registry,{kind:'prepareReservation',commandId:'intent-pending',expectedVersion:3,unitId:'u1',intentId:'intent-pending'});assert(r.ok&&'state'in r);const outcome=r.state.reservationOutcome as ReservationOutcome,intent=r.state.reservationIntent as ReservationIntent;assert.equal(outcome.status,'pending');assert.equal(outcome.reservedMinor,null);assert.equal(outcome.liabilityUpperBoundMinor,intent.initialMinor);assert(outcome.liabilityUpperBoundMinor>0);}));
test('local reservation evidence records confirmed fixture outcome without granting budget',()=>withReservationEvidence((state)=>{const loaded=runStoreCommand(state,{kind:'get',unitId:'u1'});assert(loaded.ok&&'state'in loaded);const outcome=loaded.state.reservationOutcome as ReservationOutcome;assert.equal(outcome.status,'confirmed');assert.equal(outcome.reservedMinor,outcome.liabilityUpperBoundMinor);assert.equal(outcome.productionVerified,false);assert.equal(outcome.budgetReserved,false);}));
test('ambiguous result becomes unknown and never zero liability',()=>withReservationEvidence((state,registry)=>{const changed=runReservationUnknownCommand(state,{kind:'markReservationUnknown',commandId:'unknown-1',expectedVersion:5,unitId:'u1'},()=>new Date('2026-10-03T00:06:00Z'));assert(changed.ok&&'state'in changed);const outcome=changed.state.reservationOutcome as ReservationOutcome;assert.equal(outcome.status,'unknown');assert.equal(outcome.reservedMinor,null);assert(outcome.liabilityUpperBoundMinor>0);const ready=evaluateExecutionReadiness(state,registry,'u1',()=>new Date('2026-10-03T00:06:00Z'));assert(ready.ok);assert.equal(ready.reservationStatus,'unknown');assert.equal(ready.reservationLiabilityUpperBoundMinor,outcome.liabilityUpperBoundMinor);assert(ready.blockers.includes('reservation_outcome_unknown'));}));
test('caller cannot assert a reservation outcome or zero unknown liability',()=>withReservationEvidence((state)=>{const r=runReservationUnknownCommand(state,{kind:'markReservationUnknown',commandId:'unknown-1',expectedVersion:5,unitId:'u1',status:'released',liabilityUpperBoundMinor:0});assert.equal(r.ok,false);if(!r.ok)assert.equal(r.code,'invalid_command');}));
test('signed lookup reconciliation binds receipt and exact outcome amount',()=>withReservationEvidence((state,registry,auth,anchor,a,intent,receipt)=>{assert(runReservationUnknownCommand(state,{kind:'markReservationUnknown',commandId:'unknown-1',expectedVersion:5,unitId:'u1'}).ok);const proof=signedReconciliation(a,intent,receipt.receiptId,'released'),checked=verifySignedReservationReconciliation(auth,anchor,proof,intent,receipt.receiptId,()=>new Date('2026-10-03T00:06:00Z'));assert(checked.ok);assert.equal(checked.report.outcome,'released');assert.equal(checked.report.liabilityUpperBoundMinor,0);const saved=runReservationReconciliationCommand(state,auth,anchor,{kind:'reconcileReservation',commandId:'reconcile-1',expectedVersion:6,unitId:'u1',receipt:proof},()=>new Date('2026-10-03T00:06:00Z'));assert(saved.ok&&'state'in saved);const outcome=saved.state.reservationOutcome as ReservationOutcome;assert.equal(outcome.status,'released');assert.equal(outcome.liabilityUpperBoundMinor,0);const ready=evaluateExecutionReadiness(state,registry,'u1',()=>new Date('2026-10-03T00:06:00Z'));assert(ready.ok);assert(ready.blockers.includes('reservation_released'));assert(ready.blockers.includes('production_budget_reservation_missing'));}));
test('unknown can only resolve through signed lookup or poll evidence',()=>withReservationEvidence((state,registry,auth,anchor,a,intent,receipt)=>{assert(runReservationUnknownCommand(state,{kind:'markReservationUnknown',commandId:'unknown-1',expectedVersion:5,unitId:'u1'}).ok);const proof=signedReconciliation(a,intent,receipt.receiptId,'confirmed');const blind=runStoreCommand(state,{kind:'reconcileReservation',commandId:'blind',expectedVersion:6,unitId:'u1',outcome:'released'});assert.equal(blind.ok,false);if(!blind.ok)assert.equal(blind.code,'unsupported_command');const tampered={...proof,method:'caller' as const};const rejected=runReservationReconciliationCommand(state,auth,anchor,{kind:'reconcileReservation',commandId:'reconcile-bad',expectedVersion:6,unitId:'u1',receipt:tampered},()=>new Date('2026-10-03T00:06:00Z'));assert.equal(rejected.ok,false);if(!rejected.ok)assert.equal(rejected.code,'invalid_reservation_reconciliation');const changedAmount={...proof,reservedMinor:0};const amountRejected=runReservationReconciliationCommand(state,auth,anchor,{kind:'reconcileReservation',commandId:'reconcile-amount',expectedVersion:6,unitId:'u1',receipt:changedAmount},()=>new Date('2026-10-03T00:06:00Z'));assert.equal(amountRejected.ok,false);if(!amountRejected.ok)assert.equal(amountRejected.code,'invalid_reservation_reconciliation');}));
test('unknown poll evidence preserves liability and permits a later signed poll',()=>withReservationEvidence((state,registry,auth,anchor,a,intent,receipt)=>{assert(runReservationUnknownCommand(state,{kind:'markReservationUnknown',commandId:'unknown-1',expectedVersion:5,unitId:'u1'}).ok);const stillUnknown=signedReconciliation(a,intent,receipt.receiptId,'unknown','reconcile-unknown','poll');const first=runReservationReconciliationCommand(state,auth,anchor,{kind:'reconcileReservation',commandId:'reconcile-unknown-cmd',expectedVersion:6,unitId:'u1',receipt:stillUnknown},()=>new Date('2026-10-03T00:06:00Z'));assert(first.ok&&'state'in first);assert.equal((first.state.reservationOutcome as ReservationOutcome).liabilityUpperBoundMinor,intent.initialMinor);const released=signedReconciliation(a,intent,receipt.receiptId,'released','reconcile-release','poll');const second=runReservationReconciliationCommand(state,auth,anchor,{kind:'reconcileReservation',commandId:'reconcile-release-cmd',expectedVersion:7,unitId:'u1',receipt:released},()=>new Date('2026-10-03T00:06:00Z'));assert(second.ok&&'state'in second);assert.equal((second.state.reservationOutcome as ReservationOutcome).status,'released');}));
import {inspectReservationState} from '../packages/architect/src/store.ts';
test('reservation inspection reports none without inventing zero liability',()=>withPreparedAttempt((state)=>{const report=inspectReservationState(state,'u1');assert(report.ok);assert.equal(report.status,'none');assert.equal(report.liabilityUpperBoundMinor,null);assert.equal(report.productionVerified,false);assert.equal(report.executionAllowed,false);}));
test('reservation CLI marks unknown and exposes the retained liability bound',()=>withReservationEvidence((state)=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-res-status-'));try{const file=join(d,'unknown.json');writeFileSync(file,JSON.stringify({kind:'markReservationUnknown',commandId:'unknown-cli',expectedVersion:5,unitId:'u1'}));const changed=spawnSync(process.execPath,[reservationCli,'unknown','--state',state,'--input',file],{encoding:'utf8'});assert.equal(changed.status,0,changed.stderr);const status=spawnSync(process.execPath,[reservationCli,'status','--state',state,'--unit','u1'],{encoding:'utf8'});assert.equal(status.status,0,status.stderr);const report=JSON.parse(status.stdout);assert.equal(report.status,'unknown');assert(report.liabilityUpperBoundMinor>0);assert.equal(report.reservedMinor,null);}finally{rmSync(d,{recursive:true,force:true});}}));
test('reservation CLI accepts signed poll reconciliation and reports release',()=>withReservationEvidence((state,registry,auth,anchor,a,intent,receipt)=>{const d=mkdtempSync(join(tmpdir(),'Ywoom-res-reconcile-'));try{const unknown=join(d,'unknown.json');writeFileSync(unknown,JSON.stringify({kind:'markReservationUnknown',commandId:'unknown-cli',expectedVersion:5,unitId:'u1'}));assert.equal(spawnSync(process.execPath,[reservationCli,'unknown','--state',state,'--input',unknown],{encoding:'utf8'}).status,0);const now=Date.now(),proof=signedReconciliation(a,intent,receipt.receiptId,'released','reconcile-cli','poll',new Date(now-2000).toISOString(),new Date(now-1000).toISOString(),new Date(now+600000).toISOString()),file=join(d,'reconcile.json');writeFileSync(file,JSON.stringify({kind:'reconcileReservation',commandId:'reconcile-cli-command',expectedVersion:6,unitId:'u1',receipt:proof}));const reconciled=spawnSync(process.execPath,[reservationCli,'reconcile','--state',state,'--authority',auth,'--anchor',anchor,'--input',file],{encoding:'utf8'});assert.equal(reconciled.status,0,reconciled.stderr);const status=spawnSync(process.execPath,[reservationCli,'status','--state',state,'--unit','u1'],{encoding:'utf8'});assert.equal(status.status,0,status.stderr);const report=JSON.parse(status.stdout);assert.equal(report.status,'released');assert.equal(report.liabilityUpperBoundMinor,0);assert.equal(report.reconciliationMethod,'poll');assert.equal(report.budgetReserved,false);}finally{rmSync(d,{recursive:true,force:true});}}));
